        (2, r"\text{곡선 } y = x^2-3x+2\text{ 위의 점 } (2, 0)\text{에서의 접선의 기울기는?}", "1", ["-2", "-1", "0", "2"], r"$$y' = 2x-3 \implies x=2\text{일 때 } 4-3 = 1$$", ""),
        (3, r"\text{곡선 } y = x^3\text{ 위의 점 } (1, 1)\text{에서의 접선의 방정식은?}", "y = 3x - 2", ["y = x", "y = 2x - 1", "y = 3x + 1", "y = 4x - 3"], r"기울기 $m=3(1)^2=3$. $y-1=3(x-1) \implies y=3x-2$", ""),
        (4, r"\text{곡선 } y = x^2+2x\text{ 위의 점 } (1, 3)\text{에서의 접선의 } y\text{절편은?}", "-1", ["-3", "-2", "0", "1"], r"기울기 $m=2(1)+2=4$. 접선 $y-3=4(x-1) \implies y=4x-1$. $y$절편은 $-1$", ""),
        (5, r"\text{곡선 } y = x^3-2x+1\text{ 위의 점 } (1, 0)\text{에서의 접선의 방정식은?}", "y = x - 1", ["y = -x + 1", "y = 2x - 2", "y = 3x - 3", "y = 0"], r"기울기 $m=3(1)^2-2=1$. $y-0=1(x-1) \implies y=x-1$", ""),
        (6, r"\text{곡선 } y = 2x^2-x\text{ 위의 점 } (1, 1)\text{에서의 접선의 기울기는?}", "3", ["-1", "1", "2", "4"], r"$$y' = 4x-1 \implies 4-1 = 3$$", ""),
        (7, r"\text{곡선 } y = x^3+x\text{ 위의 점 } (1, 2)\text{에서의 접선의 } y\text{절편의 절댓값 또는 값을 구하시오.}", "2", [], r"2014학년도 수능: 기울기 $4$. $y-2=4(x-1) \implies y=4x-2$", "2014학년도 수능"),
        (8, r"\text{곡선 } y = x^3-3x+5\text{ 위의 점 } (2, 7)\text{에서의 접선의 기울기를 구하시오.}", "9", [], r"2015학년도 모의평가: $y'=3x^2-3 \implies 12-3 = 9$", "2015학년도 모의평가"),
        (9, r"\text{곡선 } y = x^2+ax+1\text{ 위의 점 } (1, 3)\text{에서의 접선의 기울기가 } 5\text{일 때, } a\text{의 값을 구하시오.}", "3", [], r"2016학년도 수능: $1+a+1=3 \implies a=1$. 기울기 $2+a = 3$", "2016학년도 수능"),
        (10, r"\text{곡선 } y = x^3-4x+1\text{ 위의 점 } (2, 1)\text{에서의 접선의 기울기를 구하시오.}", "8", [], r"2017학년도 모의평가: $y'=3x^2-4 \implies 12-4 = 8$", "2017학년도 모의평가"),
        (11, r"\text{곡선 } y = x^3+2x^2-x\text{ 위의 점 } (1, 2)\text{에서의 접선의 기울기를 구하시오.}", "6", [], r"2018학년도 모의평가: $y'=3x^2+4x-1 \implies 3+4-1 = 6$", "2018학년도 모의평가"),
        (12, r"\text{곡선 } y = x^3-x+2\text{ 위의 점 } (1, 2)\text{에서의 접선의 } y\text{절편을 구하시오.}", "0", [], r"2018학년도 수능: 기울기 $2$. $y-2=2(x-1) \implies y=2x$. $y$절편은 $0$", "2018학년도 수능"),
