        (15, r"\text{곡선 } y = x^2+3\text{ 위의 점 } (1, 4)\text{에서의 접선이 점 } (0, k)\text{를 지날 때, } k\text{의 값은?}", "2", ["-2", "0", "1", "3"], r"접선 $y=2x+2$. $x=0$ 대입 시 $k=2$", ""),
        (16, r"\text{곡선 } y = -x^2+4x\text{ 위의 점 } (1, 3)\text{에서의 접선의 기울기는?}", "2", ["-2", "-1", "1", "3"], r"$$y' = -2x+4 \implies -2+4 = 2$$", ""),
        (17, r"\text{곡선 } y = x^3+ax-2\text{ 위의 점 } (1, -1)\text{에서의 접선의 기울기를 구하시오.}", "3", [], r"$1+a-2=-1 \implies a=0$. 기울기 $3x^2 = 3$", ""),
