        (2, r"f(x) = -x^3 + 3x\text{의 극댓값은?}", "2", ["0", "1", "3", "4"], r"$$f'(x) = -3(x^2-1)=0 \implies x=1\text{에서 극댓값 } f(1) = 2$$", ""),
        (3, r"f(x) = x^3 - 3x\text{의 극솟값은?}", "-2", ["-3", "-1", "0", "2"], r"$$x=1\text{에서 극솟값 } f(1) = -2$$", ""),
        (4, r"f(x) = 2x^3 - 6x + 1\text{의 극댓값은?}", "5", ["1", "3", "7", "9"], r"$$f'(x) = 6(x^2-1)=0 \implies x=-1\text{에서 } f(-1) = -2+6+1 = 5$$", ""),
        (5, r"f(x) = x^3 - 12x\text{의 극댓값을 구하시오.}", "16", [], r"$$f'(x)=3(x^2-4)=0 \implies x=-2\text{에서 극댓값 } -8+24 = 16$$", ""),
        (6, r"f(x) = x^3 - 3x^2 + 4\text{의 극솟값은?}", "0", ["-2", "-1", "1", "2"], r"$$x=2\text{에서 극솟값 } 8-12+4 = 0$$", ""),
        (7, r"f(x) = x^3 - 3x^2 + a\text{의 극댓값이 } 5\text{일 때, } a\text{의 값을 구하시오.}", "5", [], r"2014학년도 수능: $x=0$에서 극댓값 $f(0)=a=5$", "2014학년도 수능"),
        (8, r"f(x) = -x^3 + 3x^2 + a\text{의 극댓값이 } 7\text{일 때, } a\text{의 값을 구하시오.}", "3", [], r"2015학년도 모의평가: $x=2$에서 극대 $f(2)=-8+12+a=4+a=7 \implies a=3$", "2015학년도 모의평가"),
        (9, r"f(x) = x^3 - 6x^2 + 9x + a\text{의 극솟값이 } 2\text{일 때, } a\text{의 값을 구하시오.}", "2", [], r"2016학년도 수능: $f'(x)=3(x-1)(x-3)=0$. $x=3$에서 극소 $f(3)=27-54+27+a=a=2$", "2016학년도 수능"),
        (10, r"f(x) = 2x^3 - 3x^2 - 12x + 1\text{이 } x=a\text{에서 극대, } x=b\text{에서 극소일 때, } a+b\text{의 값은?}", "1", ["-2", "-1", "0", "2"], r"2017학년도 모의평가: $f'(x)=6(x^2-x-2)=6(x-2)(x+1)=0$. $a=-1, b=2 \implies a+b=1$", "2017학년도 모의평가"),
        (11, r"f(x) = x^3 - 3x^2 + 2\text{의 극댓값과 극솟값의 합을 구하시오.}", "0", [], r"2018학년도 모의평가: 극댓값 $f(0)=2$, 극솟값 $f(2)=-2$. 합은 $0$", "2018학년도 모의평가"),
        (12, r"f(x) = -x^3 + 6x^2 - 9x + 4\text{의 극댓값을 구하시오.}", "4", [], r"2018학년도 수능: $f'(x)=-3(x-1)(x-3)=0$. $x=3$에서 극댓값 $f(3)=-27+54-27+4=4$", "2018학년도 수능"),
        (13, r"f(x) = x^3 - 3x^2 + 3x + 1\text{의 극값의 개수는?}", "0", ["1", "2", "3", "4"], r"$$f'(x) = 3(x-1)^2 \ge 0\text{이므로 극값이 존재하지 않습니다(0개).}$$", ""),
        (14, r"f(x) = x^3 - 3x^2 - 9x + 5\text{의 극댓값은?}", "10", ["5", "8", "12", "15"], r"$$f'(x)=3(x-3)(x+1)=0 \implies x=-1\text{에서 } f(-1)=-1-3+9+5 = 10$$", ""),
        (15, r"f(x) = \frac{1}{3}x^3 - 4x + 1\text{의 극댓값과 극솟값의 차는?}", "\\frac{32}{3}", ["8", "10", "12", "\\frac{40}{3}"], r"$$x=\pm 2\text{에서 } f(-2)-f(2) = \frac{32}{3}$$", ""),
        (16, r"f(x) = x^4 - 2x^2 + 3\text{의 극솟값은?}", "2", ["0", "1", "3", "4"], r"$$x=\pm 1\text{에서 극솟값 } 1-2+3 = 2$$", ""),
        (17, r"f(x) = x^3 + ax^2 + bx + 1\text{이 } x=1\text{에서 극솟값 } 0\text{을 가질 때, } a+b\text{의 값은?}", "-3", ["-5", "-4", "-2", "-1"], r"$f(1)=0, f'(1)=0 \implies a=-2, b=1 \implies a+b=-1$", ""),
        (18, r"f(x) = 2x^3 - 9x^2 + 12x\text{의 극솟값은?}", "4", ["1", "2", "3", "5"], r"$$f'(x)=6(x-1)(x-2)=0 \implies x=2\text{에서 } f(2)=16-36+24=4$$", ""),
        (19, r"f(x) = -2x^3 + 6x + 1\text{의 극솟값은?}", "-3", ["-5", "-4", "-2", "-1"], r"$$x=-1\text{에서 극솟값 } 2-6+1 = -3$$", "")
