        (7, r"\int_{0}^{3} (2x-1) \,dx\text{의 값을 구하시오.}", "6", [], r"2014학년도 수능: $[x^2-x]_0^3 = 9-3 = 6$", "2014학년도 수능"),
        (8, r"\int_{1}^{2} 3x^2 \,dx\text{의 값을 구하시오.}", "7", [], r"2015학년도 모의평가: $[x^3]_1^2 = 8-1 = 7$", "2015학년도 모의평가"),
        (9, r"\int_{0}^{2} (x^3+2x) \,dx\text{의 값은?}", "8", ["4", "6", "10", "12"], r"2016학년도 수능: $[\frac{1}{4}x^4+x^2]_0^2 = 4+4 = 8$", "2016학년도 수능"),
        (10, r"\int_{1}^{3} (3x^2-2x+1) \,dx\text{의 값은?}", "20", ["16", "18", "22", "24"], r"2017학년도 모의평가: $[x^3-x^2+x]_1^3 = 21 - 1 = 20$", "2017학년도 모의평가"),
        (11, r"\int_{0}^{1} (6x^2-4x) \,dx\text{의 값은?}", "0", ["-2", "-1", "1", "2"], r"2017학년도 수능: $[2x^3-2x^2]_0^1 = 0$", "2017학년도 수능"),
        (12, r"\int_{1}^{4} (2x+3) \,dx\text{의 값을 구하시오.}", "24", [], r"2018학년도 모의평가: $[x^2+3x]_1^4 = 28 - 4 = 24$", "2018학년도 모의평가"),
        (13, r"\int_{0}^{2} (3x^2+2x) \,dx\text{의 값은?}", "12", ["6", "8", "10", "14"], r"2018학년도 수능: $[x^3+x^2]_0^2 = 8+4 = 12$", "2018학년도 수능"),
        (14, r"\int_{0}^{3} 4x \,dx\text{의 값을 구하시오.}", "18", [], r"$$[2x^2]_0^3 = 18$$", ""),
        (15, r"\int_{-2}^{2} (x^2+3) \,dx\text{의 값은?}", "\\frac{52}{3}", ["12", "14", "16", "18"], r"$$2 \int_0^2 (x^2+3) dx = 2 [\frac{8}{3}+6] = \frac{52}{3}$$", ""),
        (16, r"\int_{1}^{2} (4x^3-2x) \,dx\text{의 값을 구하시오.}", "12", [], r"$$[x^4-x^2]_1^2 = (16-4)-(1-1) = 12$$", ""),
        (17, r"\int_{0}^{1} (3x^2+2x+1) \,dx\text{의 값은?}", "3", ["1", "2", "4", "5"], r"$$[x^3+x^2+x]_0^1 = 3$$", ""),
        (18, r"\int_{1}^{3} (x-2) \,dx\text{의 값은?}", "0", ["-2", "-1", "1", "2"], r"$$[\frac{1}{2}x^2-2x]_1^3 = (\frac{9}{2}-6)-(\frac{1}{2}-2) = 0$$", ""),
        (19, r"\int_{0}^{2} (x-1)(x-2) \,dx\text{의 값은?}", "\\frac{2}{3}", ["\\frac{1}{3}", "1", "\\frac{4}{3}", "2"], r"$$[\frac{1}{3}x^3-\frac{3}{2}x^2+2x]_0^2 = \frac{8}{3}-6+4 = \frac{2}{3}$$", ""),
        (20, r"\int_{1}^{2} \frac{x^2-1}{x-1} \,dx\text{의 값은?}", "\\frac{5}{2}", ["1", "2", "3", "\\frac{7}{2}"], r"$$\int_1^2 (x+1) dx = [\frac{1}{2}x^2+x]_1^2 = 4 - \frac{3}{2} = \frac{5}{2}$$", ""),
        (21, r"\int_{0}^{a} 2x \,dx = 9\text{일 때, 양수 } a\text{의 값은?}", "3", ["1", "2", "4", "9"], r"$$a^2 = 9 \implies a = 3$$", ""),
        (22, r"\int_{0}^{1} (ax+1) \,dx = 3\text{일 때, } a\text{의 값을 구하시오.}", "4", [], r"$$\frac{a}{2}+1 = 3 \implies \frac{a}{2}=2 \implies a=4$$", ""),
        (23, r"\int_{1}^{2} 6x^2 \,dx\text{의 값을 구하시오.}", "14", [], r"$$[2x^3]_1^2 = 16-2 = 14$$", ""),
        (24, r"\int_{-1}^{1} (3x^2+2x+1) \,dx\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$$2 \int_0^1 (3x^2+1) dx = 2(1+1) = 4$$", ""),
        (25, r"\int_{0}^{2} (x^2-x) \,dx\text{의 값은?}", "\\frac{2}{3}", ["0", "\\frac{1}{3}", "1", "\\frac{4}{3}"], r"$$[\frac{1}{3}x^3-\frac{1}{2}x^2]_0^2 = \frac{8}{3}-2 = \frac{2}{3}$$", ""),
        (26, r"\int_{0}^{1} x(x-1) \,dx\text{의 값은?}", "-\\frac{1}{6}", ["-\\frac{1}{3}", "0", "\\frac{1}{6}", "\\frac{1}{3}"], r"$$[\frac{1}{3}x^3-\frac{1}{2}x^2]_0^1 = -\frac{1}{6}$$", ""),
        (27, r"\int_{1}^{3} 2x \,dx\text{의 값은?}", "8", ["4", "6", "10", "12"], r"$$[x^2]_1^3 = 9-1 = 8$$", ""),
        (28, r"\int_{0}^{2} 3(x-1)^2 \,dx\text{의 값은?}", "2", ["0", "1", "3", "4"], r"$$[(x-1)^3]_0^2 = 1 - (-1) = 2$$", ""),
        (29, r"\int_{0}^{1} (5x^4-4x^3) \,dx\text{의 값은?}", "0", ["-1", "1", "2", "3"], r"$$[x^5-x^4]_0^1 = 0$$", ""),
        (30, r"\int_{0}^{1} 2 \,dx\text{의 값을 구하시오.}", "2", [], r"$$[2x]_0^1 = 2$$", ""),
