        (1, r"\frac{d}{dx} \int_{1}^{x} (3t^2+2t) \,dt\text{의 값은?}", "3x^2+2x", ["3x^2", "6x+2", "x^3+x^2", "0"], r"미적분의 기본정리에 의해 피적분함수의 $t$에 $x$를 대입한 $3x^2+2x$입니다.", ""),
        (2, r"\frac{d}{dx} \int_{0}^{x} (t^3-1) \,dt\text{에 } x=2\text{를 대입한 값은?}", "7", ["3", "5", "8", "9"], r"$$x^3-1\text{에 } x=2\text{ 대입하면 } 8-1 = 7$$", ""),
        (3, r"\int_{1}^{x} f(t) \,dt = x^2 - 1\text{일 때, } f(2)\text{의 값은?}", "4", ["1", "2", "3", "5"], r"양변을 미분하면 $f(x) = 2x$. 따라서 $f(2) = 4$", ""),
        (4, r"\int_{0}^{x} f(t) \,dt = x^3 - 2x\text{일 때, } f(1)\text{의 값은?}", "1", ["-2", "-1", "0", "2"], r"양변을 미분하면 $f(x) = 3x^2-2$. $f(1) = 1$", ""),
        (5, r"\int_{1}^{x} f(t) \,dt = x^3 - ax\text{일 때, 상수 } a\text{의 값을 구하시오.}", "1", [], r"$x=1$ 대입: $0 = 1 - a \implies a = 1$", ""),
        (6, r"\int_{2}^{x} f(t) \,dt = x^2 + ax - 6\text{일 때, } a\text{의 값은?}", "1", ["-2", "-1", "0", "2"], r"$x=2$ 대입: $0 = 4 + 2a - 6 \implies 2a=2 \implies a=1$", ""),
        (7, r"\int_{1}^{x} f(t) \,dt = 2x^2 - ax - 1\text{일 때, } a\text{의 값을 구하시오.}", "1", [], r"2014학년도 수능: $x=1$ 대입 시 $0 = 2-a-1 \implies a=1$", "2014학년도 수능"),
        (8, r"\int_{0}^{x} f(t) \,dt = x^3 + 2x^2\text{일 때, } f(2)\text{의 값은?}", "20", ["12", "16", "24", "28"], r"2015학년도 모의평가: $f(x)=3x^2+4x \implies f(2)=12+8=20$", "2015학년도 모의평가"),
        (9, r"\int_{1}^{x} f(t) \,dt = x^2 + 3x - 4\text{일 때, } f(3)\text{의 값은?}", "9", ["5", "7", "11", "13"], r"2016학년도 수능: $f(x)=2x+3 \implies f(3)=9$", "2016학년도 수능"),
        (10, r"\int_{2}^{x} f(t) \,dt = x^3 - 4x\text{일 때, } f(3)\text{의 값을 구하시오.}", "23", [], r"2017학년도 모의평가: $f(x)=3x^2-4 \implies f(3)=27-4=23$", "2017학년도 모의평가"),
        (11, r"\int_{1}^{x} f(t) \,dt = x^3 + ax - 3\text{일 때, } f(2)\text{의 값을 구하시오.}", "14", [], r"2018학년도 수능: $x=1 \implies a=2$. $f(x)=3x^2+2 \implies f(2)=14$", "2018학년도 수능"),
        (12, r"\int_{a}^{x} f(t) \,dt = x^2 - 9\text{일 때, 양수 } a\text{의 값을 구하시오.}", "3", [], r"$$a^2-9=0 \implies a=3$$", ""),
        (13, r"\frac{d}{dx} \int_{2}^{x} (4t+1) \,dt\text{의 값은?}", "4x+1", ["4x", "2x^2+x", "4", "0"], r"미분하면 $4x+1$입니다.", ""),
        (14, r"\int_{0}^{x} f(t) \,dt = x^2 + 4x\text{일 때, } f(1)\text{의 값은?}", "6", ["2", "4", "8", "10"], r"$f(x)=2x+4 \implies f(1)=6$", ""),
