        (6, r"\text{곡선 } y = x^3\text{과 } x\text{축 및 직선 } x=1\text{로 둘러싸인 도형의 넓이는?}", "\\frac{1}{4}", ["\\frac{1}{8}", "\\frac{1}{3}", "\\frac{1}{2}", "1"], r"$$S = \int_0^1 x^3 dx = \frac{1}{4}$$", ""),
        (7, r"\text{곡선 } y = x(x-1)\text{과 } x\text{축으로 둘러싸인 도형의 넓이는?}", "\\frac{1}{6}", ["\\frac{1}{12}", "\\frac{1}{4}", "\\frac{1}{3}", "\\frac{1}{2}"], r"2014학년도 수능: $\frac{1}{6}(1)^3 = \frac{1}{6}$", "2014학년도 수능"),
        (8, r"\text{곡선 } y = x(4-x)\text{와 } x\text{축으로 둘러싸인 도형의 넓이는?}", "\\frac{32}{3}", ["8", "10", "\\frac{28}{3}", "12"], r"2015학년도 모의평가: $\frac{1}{6}(4)^3 = \frac{32}{3}$", "2015학년도 모의평가"),
        (9, r"\text{곡선 } y = 3x^2\text{과 } x\text{축 및 직선 } x=2\text{로 둘러싸인 도형의 넓이를 구하시오.}", "8", [], r"2016학년도 수능: $[x^3]_0^2 = 8$", "2016학년도 수능"),
        (10, r"\text{곡선 } y = 2x\text{와 } x\text{축 및 직선 } x=3\text{으로 둘러싸인 도형의 넓이를 구하시오.}", "9", [], r"2017학년도 모의평가: $[x^2]_0^3 = 9$", "2017학년도 모의평가"),
        (11, r"\text{곡선 } y = x^2-4\text{와 } x\text{축으로 둘러싸인 도형의 넓이는?}", "\\frac{32}{3}", ["8", "10", "\\frac{28}{3}", "12"], r"2018학년도 모의평가: $\frac{1}{6}(4)^3 = \frac{32}{3}$", "2018학년도 모의평가"),
        (12, r"\text{곡선 } y = 6x(1-x)\text{와 } x\text{축으로 둘러싸인 도형의 넓이는?}", "1", ["\\frac{1}{2}", "2", "3", "4"], r"2018학년도 수능: $\frac{6}{6}(1)^3 = 1$", "2018학년도 수능"),
        (13, r"\text{곡선 } y = x(x-3)\text{과 } x\text{축으로 둘러싸인 도형의 넓이를 구하시오.}", "\\frac{9}{2}", [], r"$$\frac{1}{6}(3)^3 = \frac{9}{2}$$", ""),
        (14, r"\text{곡선 } y = -x^2+x\text{와 } x\text{축으로 둘러싸인 도형의 넓이는?}", "\\frac{1}{6}", ["\\frac{1}{12}", "\\frac{1}{4}", "\\frac{1}{3}", "\\frac{1}{2}"], r"$$\frac{1}{6}(1)^3 = \frac{1}{6}$$", ""),
        (15, r"\text{곡선 } y = x^2-2x\text{와 } x\text{축으로 둘러싸인 도형의 넓이는?}", "\\frac{4}{3}", ["\\frac{2}{3}", "1", "\\frac{5}{3}", "2"], r"$$\frac{1}{6}(2)^3 = \frac{4}{3}$$", ""),
        (16, r"\text{곡선 } y = 2x^2\text{과 } x\text{축 및 직선 } x=3\text{으로 둘러싸인 도형의 넓이는?}", "18", ["12", "15", "21", "24"], r"$$[\frac{2}{3}x^3]_0^3 = 18$$", ""),
